import 'package:shikai_app/models/anilist_media.dart';

/// Pre-seeded offline & rate-limit resilience curated datasets
/// Ensures that manga catalog is NEVER empty (0 titles) under any network condition!
class MangaCuratedData {
  static final List<AnilistMedia> curatedAll = _allRaw.map((j) => AnilistMedia.fromJson(Map<String, dynamic>.from(j)..['type'] = 'MANGA')).toList();
  static final List<AnilistMedia> curatedManga = _mangaRaw.map((j) => AnilistMedia.fromJson(Map<String, dynamic>.from(j)..['type'] = 'MANGA')).toList();
  static final List<AnilistMedia> curatedManhwa = _manhwaRaw.map((j) => AnilistMedia.fromJson(Map<String, dynamic>.from(j)..['type'] = 'MANGA')).toList();
  static final List<AnilistMedia> curatedManhua = _manhuaRaw.map((j) => AnilistMedia.fromJson(Map<String, dynamic>.from(j)..['type'] = 'MANGA')).toList();

  static List<AnilistMedia> getForCategory(String category) {
    final cat = category.toLowerCase().trim();
    if (cat == 'manhwa') return curatedManhwa;
    if (cat == 'manhua') return curatedManhua;
    if (cat == 'manga') return curatedManga;
    return curatedAll;
  }

  static final List<Map<String, dynamic>> _allRaw = [{"id": 105778, "title": {"romaji": "Chainsaw Man", "english": "Chainsaw Man"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx105778-euxXZEIfDY2u.png", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx105778-euxXZEIfDY2u.png", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx105778-euxXZEIfDY2u.png"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/105778-ppHaMwown6c9.jpg", "description": "The name says it all! Denji's life of poverty is changed forever when he merges with his pet chainsaw dog, Pochita! Now he's living in the big city and an official Devil Hunter. But he's got a lot to learn about his new job and chainsaw powers!<br>\n<br>\n(Source: MANGA Plus)<br>\n<br>\n<i>Notes:<br>\n- Nominated for the 2020 Manga Taisho Award.<br>\n- Winner of the 2021 Kono Manga ga Sugoi Award.<br>\n- Winner of the 66th Shogakukan Manga Award in the shounen category.<br>\n- Winner of the 2021 and 2022 Harvey Award for Best Manga.<br>\n- Chapters 1-97 were released in Weekly Shounen Jump from Dec 3, 2018 to Dec 13, 2020. The series resumed from Ch. 98 in Shounen Jump+ on July 12, 2022</i>", "chapters": 232, "genres": ["Action", "Comedy", "Drama", "Horror", "Supernatural"], "averageScore": 84, "status": "FINISHED", "format": "MANGA", "countryOfOrigin": "JP"}, {"id": 105398, "title": {"romaji": "Na Honjaman Level Up", "english": "Solo Leveling"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx105398-b673Vt5ZSuz3.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx105398-b673Vt5ZSuz3.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx105398-b673Vt5ZSuz3.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/105398-4UrEhdqZukrg.jpg", "description": "In a world where awakened beings called “Hunters” must battle deadly monsters to protect humanity, Seong Jin-U, nicknamed “the weakest hunter of all mankind,” finds himself in a constant struggle for survival. One day, after a brutal encounter in an overpowered dungeon wipes out his party and threatens to end his life, a mysterious System chooses him as its sole player: Jin-U has been granted the rare opportunity to level up his abilities, possibly beyond any known limits. Follow Jin-U’s journey as he takes on ever-stronger enemies, both human and monster, to discover the secrets deep within the dungeons and the ultimate extent of his powers.\n<br><br>\n(Source: Tappytoon)\n<br><br>\n<i>Note: Includes 22 extra chapters.</i>", "chapters": 201, "genres": ["Action", "Adventure", "Fantasy"], "averageScore": 84, "status": "FINISHED", "format": "MANGA", "countryOfOrigin": "KR"}, {"id": 101517, "title": {"romaji": "Jujutsu Kaisen", "english": "Jujutsu Kaisen"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx101517-H3TdM3g5ZUe9.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx101517-H3TdM3g5ZUe9.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx101517-H3TdM3g5ZUe9.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/101517-FrJtb3Th3HtF.jpg", "description": "Although Yuji Itadori looks like your average teenager, his immense physical strength is something to behold! Every sports club wants him to join, but Itadori would rather hang out with the school outcasts in the Occult Research Club. One day, the club manages to get their hands on a sealed cursed object. Little do they know the terror they’ll unleash when they break the seal…\n<br><br>\n(Source: VIZ Media)\n<br><br>\n<i>Notes:<br>\n- Ranked 1st in Japan's Bookstore Employees Top Manga of 2018.<br>\n- Nominated for the 25th Annual Tezuka Osamu Cultural Prize in 2021.<br>\n- Nominated for the 65th Shogakukan Manga Award in the Shounen Category in 2019.<br>\n- Includes one extra chapter.</i>", "chapters": 272, "genres": ["Action", "Drama", "Supernatural"], "averageScore": 80, "status": "FINISHED", "format": "MANGA", "countryOfOrigin": "JP"}, {"id": 30002, "title": {"romaji": "Berserk", "english": "Berserk"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx30002-Cul4OeN7bYtn.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx30002-Cul4OeN7bYtn.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx30002-Cul4OeN7bYtn.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/30002-3TuoSMl20fUX.jpg", "description": "His name is Guts, the Black Swordsman, a feared warrior spoken of only in whispers. Bearer of a gigantic sword, an iron hand, and the scars of countless battles and tortures, his flesh is also indelibly marked with The Brand, an unholy symbol that draws the forces of darkness to him and dooms him as their sacrifice. But Guts won't take his fate lying down; he'll cut a crimson swath of carnage through the ranks of the damned—and anyone else foolish enough to oppose him! Accompanied by Puck the Elf, more an annoyance than a companion, Guts relentlessly follows a dark, bloodstained path that leads only to death...or vengeance.<br>\n<br>\n(Source: Dark Horse)<br>\n<br>\n<i>Notes:<br>\n- Volumes 1-5 contain the 16 prequel chapters 0A - 0P.<br>\n- <a href=\"https://anilist.co/manga/95821/\">Chapter 83</a> was omitted from Volume 13 due to the author’s request.<br>\n- Volume 14 includes “<a href=\"https://anilist.co/manga/36408/\">Berserk: The Prototype</a>”.<br>\n- Due to the author's passing, starting from Chapter 365, the manga is illustrated by Studio Gaga (Miura's assistants) and supervised by Kouji Mori (a close friend of Miura's).</i>", "chapters": null, "genres": ["Action", "Adventure", "Drama", "Fantasy", "Horror", "Psychological"], "averageScore": 92, "status": "RELEASING", "format": "MANGA", "countryOfOrigin": "JP"}, {"id": 30013, "title": {"romaji": "ONE PIECE", "english": "One Piece"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx30013-BeslEMqiPhlk.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx30013-BeslEMqiPhlk.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx30013-BeslEMqiPhlk.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/30013-hbbRZqC5MjYh.jpg", "description": "As a child, Monkey D. Luffy was inspired to become a pirate by listening to the tales of the buccaneer \"Red-Haired\" Shanks. But his life changed when Luffy accidentally ate the Gum-Gum Devil Fruit and gained the power to stretch like rubber...at the cost of never being able to swim again! Years later, still vowing to become the king of the pirates, Luffy sets out on his adventure...one guy alone in a rowboat, in search of the legendary \"One Piece,\" said to be the greatest treasure in the world...\n<br><br>\n(Source: VIZ Media)", "chapters": null, "genres": ["Action", "Adventure", "Comedy", "Fantasy"], "averageScore": 91, "status": "RELEASING", "format": "MANGA", "countryOfOrigin": "JP"}, {"id": 53390, "title": {"romaji": "Shingeki no Kyojin", "english": "Attack on Titan"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx53390-1RsuABC34P9D.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx53390-1RsuABC34P9D.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx53390-1RsuABC34P9D.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/53390-6Uru5rrjh8zv.jpg", "description": "In this post-apocalyptic sci-fi story, humanity has been devastated by the bizarre, giant humanoids known as the Titans. Little is known about where they came from or why they are bent on consuming mankind. Seemingly unintelligent, they have roamed the world for years, killing everyone they see. For the past century, what's left of man has hidden in a giant, three-walled city. People believe their 50-meter-high walls will protect them from the Titans, but the sudden appearance of an immense Titan is about to change everything.\n<br><br>\n(Source: Kodansha USA)\n<br><br>\n<i>Note: Includes two extra chapters.</i>", "chapters": 141, "genres": ["Action", "Drama", "Fantasy", "Mystery"], "averageScore": 84, "status": "FINISHED", "format": "MANGA", "countryOfOrigin": "JP"}, {"id": 87216, "title": {"romaji": "Kimetsu no Yaiba", "english": "Demon Slayer: Kimetsu no Yaiba"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx87216-c9bSNVD10UuD.png", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx87216-c9bSNVD10UuD.png", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx87216-c9bSNVD10UuD.png"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/87216-TVKEGfSxAqKs.jpg", "description": "The setting is Taisho era Japan. Tanjirou is a kindhearted young boy who lived peacefully with his family as a coal seller. Their normal life changes completely when his family is slaughtered by demons. The only other survivor, Tanjirou's younger sister Nezuko, has become a ferocious demon. In order to return Nezuko to normal and get revenge on the demon that killed their family, the two of them depart on a journey. From a young talent, an adventure tale of blood and swords begins!\n<br><br>\n(Source: Shonen Jump)\n<br><br>\n<i>Notes:<br>\n- Includes two extra chapters.<br> \n- Nominated to the 24th and 25th Annual Tezuka Osamu Cultural Prize.</i>", "chapters": 207, "genres": ["Action", "Adventure", "Drama", "Supernatural"], "averageScore": 79, "status": "FINISHED", "format": "MANGA", "countryOfOrigin": "JP"}, {"id": 63327, "title": {"romaji": "Tokyo Ghoul", "english": "Tokyo Ghoul"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx63327-glC9cDxYBja9.png", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx63327-glC9cDxYBja9.png", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx63327-glC9cDxYBja9.png"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/63327-uaFaG1HAJ0tK.jpg", "description": "Shy Ken Kaneki is thrilled to go on a date with the beautiful Rize. But it turns out that she’s only interested in his body—eating it, that is. When a morally questionable rescue transforms him into the first half-human half-Ghoul hybrid, Ken is drawn into the dark and violent world of Ghouls, which exists alongside our own.\n<br><br>\n(Source: VIZ Media)\n<br><br>\n<i>Note: Includes one extra chapter.</i>", "chapters": 144, "genres": ["Action", "Horror", "Mystery", "Psychological", "Supernatural"], "averageScore": 85, "status": "FINISHED", "format": "MANGA", "countryOfOrigin": "JP"}, {"id": 34632, "title": {"romaji": "Oyasumi Punpun", "english": "Goodnight Punpun"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx34632-5xMDkx3pXsEh.png", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx34632-5xMDkx3pXsEh.png", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx34632-5xMDkx3pXsEh.png"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/34632-JULTgA6q6jAH.jpg", "description": "Meet Punpun Punyama. He’s an average kid in an average town.<br>\nHe wants to win a Nobel Prize and save the world.<br>\nHe wants the girl he has a crush on to like him back.<br>\nHe wants to find some porn.<br>\nThat’s what he wants, but what does he get…?\n<br><br>\n(Source: VIZ Media)", "chapters": 147, "genres": ["Drama", "Psychological", "Slice of Life"], "averageScore": 88, "status": "FINISHED", "format": "MANGA", "countryOfOrigin": "JP"}, {"id": 85486, "title": {"romaji": "Boku no Hero Academia", "english": "My Hero Academia"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx85486-INqnYx8gL3eX.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx85486-INqnYx8gL3eX.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx85486-INqnYx8gL3eX.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/85486-4mTRih1qOdgk.jpg", "description": "Middle school student Izuku Midoriya wants to be a hero more than anything, but he hasn’t got an ounce of power in him. With no chance of ever getting into the prestigious U.A. High School for budding heroes, his life is looking more and more like a dead end. Then an encounter with All Might, the greatest hero of them all, gives him a chance to change his destiny…<br><br>(Source: VIZ Media)\n<br><br>\n<i>Note:<br>\n- Winner of the 1st Next Manga Award in the Print Category in 2015.<br>\n- Nominated for the 8th Manga Taisho Award in 2015.<br> \n- Nominated for the 40th Kodansha Manga Award in the Shounen Category in 2016.<br> \n- Includes one extra chapter.</i>", "chapters": 432, "genres": ["Action", "Adventure", "Comedy", "Drama", "Fantasy"], "averageScore": 78, "status": "FINISHED", "format": "MANGA", "countryOfOrigin": "JP"}, {"id": 74347, "title": {"romaji": "One Punch-Man", "english": "One-Punch Man"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx74347-sZpmNJ5xLwRK.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx74347-sZpmNJ5xLwRK.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx74347-sZpmNJ5xLwRK.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/74347-xAQI9BxcpWM3.jpg", "description": "In this new action-comedy, everything about a young man named Saitama screams \"AVERAGE,&rdquo; from his lifeless expression, to his bald head, to his unimpressive physique. However, this average-looking fellow doesn't have your average problem... He's actually a superhero that's looking for tough opponents! The problem is, every time he finds a promising candidate he beats the snot out of them in one punch. Can Saitama finally find an evil villain strong enough to challenge him? Follow Saitama through his hilarious romps as he searches for new bad guys to challenge!\n<br><br>\n(Source: VIZ Media)", "chapters": null, "genres": ["Action", "Comedy", "Sci-Fi", "Supernatural"], "averageScore": 85, "status": "RELEASING", "format": "MANGA", "countryOfOrigin": "JP"}, {"id": 30656, "title": {"romaji": "Vagabond", "english": "Vagabond"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx30656-9mW113O7rDnA.png", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx30656-9mW113O7rDnA.png", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx30656-9mW113O7rDnA.png"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/30656-XYzvRlsc3iK4.jpg", "description": "At seventeen years of age, Miyamoto Musashi--still known by his childhood name, Shinmen Takezo--was a wild young brute just setting out along the way of the sword.\n<br><br>\nIn the aftermath of the epic Battle of Sekigahara, Takezo finds himself a fugitive survivor on the losing side of the war. Takezo's vicious nature has made him an outcast even in his own village, and he is hunted down like an animal. At this crucial crossroads in Takezo's life, an eccentric monk and a childhood friend are the only ones who can help him find his way.<br><br>(Source: VIZ Media)", "chapters": null, "genres": ["Action", "Adventure", "Drama"], "averageScore": 91, "status": "RELEASING", "format": "MANGA", "countryOfOrigin": "JP"}, {"id": 108556, "title": {"romaji": "SPY×FAMILY", "english": "SPY x FAMILY"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx108556-NHjkz0BNJhLx.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx108556-NHjkz0BNJhLx.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx108556-NHjkz0BNJhLx.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/108556-iCiPfU0GU4OM.jpg", "description": "The master spy codenamed &lt;Twilight&gt; has spent his days on undercover missions, all for the dream of a better world. But one day, he receives a particularly difficult new order from command. For his mission, he must form a temporary family and start a new life?! A Spy/Action/Comedy about a one-of-a-kind family!<br><br>\n(Source: MANGA Plus)<br><br>\n<i>Notes:<br>\n- Nominated for the 24th Tezuka Osamu Cultural Prize in 2020.<br>\n- Nominated for the 13th and 14th Manga Taisho Award in 2020 and 2021.<br>\n- Nominated for the 44th Kodansha Manga Award in the Shounen Category in 2020.</i>", "chapters": null, "genres": ["Action", "Comedy", "Slice of Life", "Supernatural"], "averageScore": 83, "status": "RELEASING", "format": "MANGA", "countryOfOrigin": "JP"}, {"id": 30642, "title": {"romaji": "Vinland Saga", "english": "Vinland Saga"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx30642-0mjRDkf4THpo.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx30642-0mjRDkf4THpo.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx30642-0mjRDkf4THpo.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/30642-MeizzL2WDv6C.jpg", "description": "As a child, Thorfinn sat at the feet of the great Leif Ericson and thrilled to wild tales of a land far to the west. But his youthful fantasies were shattered by a mercenary raid. Raised by the Vikings who murdered his father, Thorfinn became a terrifying warrior, forever seeking to kill the band's leader, Askeladd, and avenge his father. Sustaining Thorfinn through his ordeal are his pride in his family and his dreams of a fertile westward land, a land without war or slavery … the land Leif called Vinland.\n<br><br>\n(Source: Kodansha USA)\n<br><br>\n<i>Notes:<br>\n- Includes the one-shot \"Sayonara ga Chikai no de\" (For Our Farewell Is Near)<br>\n- Includes the one-shot \"Assassin's Creed: Valhalla x Vinland Saga\"<br>\n- Includes two extra chapters.<br>\n- Won the Grand Prize at the Japan Media Arts Festival in 2009.<br>\n- Winner of the 36th Kodansha Manga Award in the General category in 2012.</i>", "chapters": 224, "genres": ["Action", "Adventure", "Drama"], "averageScore": 90, "status": "FINISHED", "format": "MANGA", "countryOfOrigin": "JP"}, {"id": 87423, "title": {"romaji": "Yakusoku no Neverland", "english": "The Promised Neverland"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx87423-gPNtu8QbGped.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx87423-gPNtu8QbGped.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx87423-gPNtu8QbGped.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/n87423-n5n0LZu9Gs5H.jpg", "description": "Emma, Norman and Ray are the brightest kids at the Grace Field House orphanage. And under the care of the woman they refer to as “Mom,” all the kids have enjoyed a comfortable life. Good food, clean clothes and the perfect environment to learn—what more could an orphan ask for? One day, though, Emma and Norman uncover the dark truth of the outside world they are forbidden from seeing.\n<br><br>\n(Source: VIZ Media)\n<br><br>\n<i>Note: Nominated to the 22nd, 23rd, and 25th Annual Tezuka Osamu Cultural Prize.</i>", "chapters": 181, "genres": ["Drama", "Fantasy", "Horror", "Mystery", "Psychological", "Thriller"], "averageScore": 79, "status": "FINISHED", "format": "MANGA", "countryOfOrigin": "JP"}, {"id": 119257, "title": {"romaji": "Jeonjijeok Dokja Sijeom", "english": "Omniscient Reader"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx119257-Pi21aq3ey9GG.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx119257-Pi21aq3ey9GG.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx119257-Pi21aq3ey9GG.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/119257-RtxJMRCunHXc.jpg", "description": "Back then, Dok-Ja had no idea. He had no idea his favorite web novel 'Three Ways to Survive the Apocalypse' was going to come to life, and that he would become the only person to know how the world was going to end. He also had no idea he would end up becoming the protagonist of this novel-turned-reality. Now, Dok-Ja will go on a journey to change the course of the story and save humankind once and for all.\n<br><br>\n(Source: WEBTOON, edited)", "chapters": null, "genres": ["Action", "Adventure", "Fantasy"], "averageScore": 86, "status": "RELEASING", "format": "MANGA", "countryOfOrigin": "KR"}];
  static final List<Map<String, dynamic>> _mangaRaw = [{"id": 105778, "title": {"romaji": "Chainsaw Man", "english": "Chainsaw Man"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx105778-euxXZEIfDY2u.png", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx105778-euxXZEIfDY2u.png", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx105778-euxXZEIfDY2u.png"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/105778-ppHaMwown6c9.jpg", "description": "The name says it all! Denji's life of poverty is changed forever when he merges with his pet chainsaw dog, Pochita! Now he's living in the big city and an official Devil Hunter. But he's got a lot to learn about his new job and chainsaw powers!<br>\n<br>\n(Source: MANGA Plus)<br>\n<br>\n<i>Notes:<br>\n- Nominated for the 2020 Manga Taisho Award.<br>\n- Winner of the 2021 Kono Manga ga Sugoi Award.<br>\n- Winner of the 66th Shogakukan Manga Award in the shounen category.<br>\n- Winner of the 2021 and 2022 Harvey Award for Best Manga.<br>\n- Chapters 1-97 were released in Weekly Shounen Jump from Dec 3, 2018 to Dec 13, 2020. The series resumed from Ch. 98 in Shounen Jump+ on July 12, 2022</i>", "chapters": 232, "genres": ["Action", "Comedy", "Drama", "Horror", "Supernatural"], "averageScore": 84, "status": "FINISHED", "format": "MANGA", "countryOfOrigin": "JP"}, {"id": 101517, "title": {"romaji": "Jujutsu Kaisen", "english": "Jujutsu Kaisen"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx101517-H3TdM3g5ZUe9.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx101517-H3TdM3g5ZUe9.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx101517-H3TdM3g5ZUe9.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/101517-FrJtb3Th3HtF.jpg", "description": "Although Yuji Itadori looks like your average teenager, his immense physical strength is something to behold! Every sports club wants him to join, but Itadori would rather hang out with the school outcasts in the Occult Research Club. One day, the club manages to get their hands on a sealed cursed object. Little do they know the terror they’ll unleash when they break the seal…\n<br><br>\n(Source: VIZ Media)\n<br><br>\n<i>Notes:<br>\n- Ranked 1st in Japan's Bookstore Employees Top Manga of 2018.<br>\n- Nominated for the 25th Annual Tezuka Osamu Cultural Prize in 2021.<br>\n- Nominated for the 65th Shogakukan Manga Award in the Shounen Category in 2019.<br>\n- Includes one extra chapter.</i>", "chapters": 272, "genres": ["Action", "Drama", "Supernatural"], "averageScore": 80, "status": "FINISHED", "format": "MANGA", "countryOfOrigin": "JP"}, {"id": 30002, "title": {"romaji": "Berserk", "english": "Berserk"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx30002-Cul4OeN7bYtn.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx30002-Cul4OeN7bYtn.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx30002-Cul4OeN7bYtn.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/30002-3TuoSMl20fUX.jpg", "description": "His name is Guts, the Black Swordsman, a feared warrior spoken of only in whispers. Bearer of a gigantic sword, an iron hand, and the scars of countless battles and tortures, his flesh is also indelibly marked with The Brand, an unholy symbol that draws the forces of darkness to him and dooms him as their sacrifice. But Guts won't take his fate lying down; he'll cut a crimson swath of carnage through the ranks of the damned—and anyone else foolish enough to oppose him! Accompanied by Puck the Elf, more an annoyance than a companion, Guts relentlessly follows a dark, bloodstained path that leads only to death...or vengeance.<br>\n<br>\n(Source: Dark Horse)<br>\n<br>\n<i>Notes:<br>\n- Volumes 1-5 contain the 16 prequel chapters 0A - 0P.<br>\n- <a href=\"https://anilist.co/manga/95821/\">Chapter 83</a> was omitted from Volume 13 due to the author’s request.<br>\n- Volume 14 includes “<a href=\"https://anilist.co/manga/36408/\">Berserk: The Prototype</a>”.<br>\n- Due to the author's passing, starting from Chapter 365, the manga is illustrated by Studio Gaga (Miura's assistants) and supervised by Kouji Mori (a close friend of Miura's).</i>", "chapters": null, "genres": ["Action", "Adventure", "Drama", "Fantasy", "Horror", "Psychological"], "averageScore": 92, "status": "RELEASING", "format": "MANGA", "countryOfOrigin": "JP"}, {"id": 30013, "title": {"romaji": "ONE PIECE", "english": "One Piece"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx30013-BeslEMqiPhlk.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx30013-BeslEMqiPhlk.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx30013-BeslEMqiPhlk.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/30013-hbbRZqC5MjYh.jpg", "description": "As a child, Monkey D. Luffy was inspired to become a pirate by listening to the tales of the buccaneer \"Red-Haired\" Shanks. But his life changed when Luffy accidentally ate the Gum-Gum Devil Fruit and gained the power to stretch like rubber...at the cost of never being able to swim again! Years later, still vowing to become the king of the pirates, Luffy sets out on his adventure...one guy alone in a rowboat, in search of the legendary \"One Piece,\" said to be the greatest treasure in the world...\n<br><br>\n(Source: VIZ Media)", "chapters": null, "genres": ["Action", "Adventure", "Comedy", "Fantasy"], "averageScore": 91, "status": "RELEASING", "format": "MANGA", "countryOfOrigin": "JP"}, {"id": 53390, "title": {"romaji": "Shingeki no Kyojin", "english": "Attack on Titan"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx53390-1RsuABC34P9D.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx53390-1RsuABC34P9D.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx53390-1RsuABC34P9D.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/53390-6Uru5rrjh8zv.jpg", "description": "In this post-apocalyptic sci-fi story, humanity has been devastated by the bizarre, giant humanoids known as the Titans. Little is known about where they came from or why they are bent on consuming mankind. Seemingly unintelligent, they have roamed the world for years, killing everyone they see. For the past century, what's left of man has hidden in a giant, three-walled city. People believe their 50-meter-high walls will protect them from the Titans, but the sudden appearance of an immense Titan is about to change everything.\n<br><br>\n(Source: Kodansha USA)\n<br><br>\n<i>Note: Includes two extra chapters.</i>", "chapters": 141, "genres": ["Action", "Drama", "Fantasy", "Mystery"], "averageScore": 84, "status": "FINISHED", "format": "MANGA", "countryOfOrigin": "JP"}, {"id": 87216, "title": {"romaji": "Kimetsu no Yaiba", "english": "Demon Slayer: Kimetsu no Yaiba"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx87216-c9bSNVD10UuD.png", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx87216-c9bSNVD10UuD.png", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx87216-c9bSNVD10UuD.png"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/87216-TVKEGfSxAqKs.jpg", "description": "The setting is Taisho era Japan. Tanjirou is a kindhearted young boy who lived peacefully with his family as a coal seller. Their normal life changes completely when his family is slaughtered by demons. The only other survivor, Tanjirou's younger sister Nezuko, has become a ferocious demon. In order to return Nezuko to normal and get revenge on the demon that killed their family, the two of them depart on a journey. From a young talent, an adventure tale of blood and swords begins!\n<br><br>\n(Source: Shonen Jump)\n<br><br>\n<i>Notes:<br>\n- Includes two extra chapters.<br> \n- Nominated to the 24th and 25th Annual Tezuka Osamu Cultural Prize.</i>", "chapters": 207, "genres": ["Action", "Adventure", "Drama", "Supernatural"], "averageScore": 79, "status": "FINISHED", "format": "MANGA", "countryOfOrigin": "JP"}, {"id": 63327, "title": {"romaji": "Tokyo Ghoul", "english": "Tokyo Ghoul"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx63327-glC9cDxYBja9.png", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx63327-glC9cDxYBja9.png", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx63327-glC9cDxYBja9.png"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/63327-uaFaG1HAJ0tK.jpg", "description": "Shy Ken Kaneki is thrilled to go on a date with the beautiful Rize. But it turns out that she’s only interested in his body—eating it, that is. When a morally questionable rescue transforms him into the first half-human half-Ghoul hybrid, Ken is drawn into the dark and violent world of Ghouls, which exists alongside our own.\n<br><br>\n(Source: VIZ Media)\n<br><br>\n<i>Note: Includes one extra chapter.</i>", "chapters": 144, "genres": ["Action", "Horror", "Mystery", "Psychological", "Supernatural"], "averageScore": 85, "status": "FINISHED", "format": "MANGA", "countryOfOrigin": "JP"}, {"id": 34632, "title": {"romaji": "Oyasumi Punpun", "english": "Goodnight Punpun"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx34632-5xMDkx3pXsEh.png", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx34632-5xMDkx3pXsEh.png", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx34632-5xMDkx3pXsEh.png"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/34632-JULTgA6q6jAH.jpg", "description": "Meet Punpun Punyama. He’s an average kid in an average town.<br>\nHe wants to win a Nobel Prize and save the world.<br>\nHe wants the girl he has a crush on to like him back.<br>\nHe wants to find some porn.<br>\nThat’s what he wants, but what does he get…?\n<br><br>\n(Source: VIZ Media)", "chapters": 147, "genres": ["Drama", "Psychological", "Slice of Life"], "averageScore": 88, "status": "FINISHED", "format": "MANGA", "countryOfOrigin": "JP"}, {"id": 85486, "title": {"romaji": "Boku no Hero Academia", "english": "My Hero Academia"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx85486-INqnYx8gL3eX.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx85486-INqnYx8gL3eX.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx85486-INqnYx8gL3eX.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/85486-4mTRih1qOdgk.jpg", "description": "Middle school student Izuku Midoriya wants to be a hero more than anything, but he hasn’t got an ounce of power in him. With no chance of ever getting into the prestigious U.A. High School for budding heroes, his life is looking more and more like a dead end. Then an encounter with All Might, the greatest hero of them all, gives him a chance to change his destiny…<br><br>(Source: VIZ Media)\n<br><br>\n<i>Note:<br>\n- Winner of the 1st Next Manga Award in the Print Category in 2015.<br>\n- Nominated for the 8th Manga Taisho Award in 2015.<br> \n- Nominated for the 40th Kodansha Manga Award in the Shounen Category in 2016.<br> \n- Includes one extra chapter.</i>", "chapters": 432, "genres": ["Action", "Adventure", "Comedy", "Drama", "Fantasy"], "averageScore": 78, "status": "FINISHED", "format": "MANGA", "countryOfOrigin": "JP"}, {"id": 74347, "title": {"romaji": "One Punch-Man", "english": "One-Punch Man"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx74347-sZpmNJ5xLwRK.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx74347-sZpmNJ5xLwRK.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx74347-sZpmNJ5xLwRK.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/74347-xAQI9BxcpWM3.jpg", "description": "In this new action-comedy, everything about a young man named Saitama screams \"AVERAGE,&rdquo; from his lifeless expression, to his bald head, to his unimpressive physique. However, this average-looking fellow doesn't have your average problem... He's actually a superhero that's looking for tough opponents! The problem is, every time he finds a promising candidate he beats the snot out of them in one punch. Can Saitama finally find an evil villain strong enough to challenge him? Follow Saitama through his hilarious romps as he searches for new bad guys to challenge!\n<br><br>\n(Source: VIZ Media)", "chapters": null, "genres": ["Action", "Comedy", "Sci-Fi", "Supernatural"], "averageScore": 85, "status": "RELEASING", "format": "MANGA", "countryOfOrigin": "JP"}, {"id": 30656, "title": {"romaji": "Vagabond", "english": "Vagabond"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx30656-9mW113O7rDnA.png", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx30656-9mW113O7rDnA.png", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx30656-9mW113O7rDnA.png"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/30656-XYzvRlsc3iK4.jpg", "description": "At seventeen years of age, Miyamoto Musashi--still known by his childhood name, Shinmen Takezo--was a wild young brute just setting out along the way of the sword.\n<br><br>\nIn the aftermath of the epic Battle of Sekigahara, Takezo finds himself a fugitive survivor on the losing side of the war. Takezo's vicious nature has made him an outcast even in his own village, and he is hunted down like an animal. At this crucial crossroads in Takezo's life, an eccentric monk and a childhood friend are the only ones who can help him find his way.<br><br>(Source: VIZ Media)", "chapters": null, "genres": ["Action", "Adventure", "Drama"], "averageScore": 91, "status": "RELEASING", "format": "MANGA", "countryOfOrigin": "JP"}, {"id": 108556, "title": {"romaji": "SPY×FAMILY", "english": "SPY x FAMILY"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx108556-NHjkz0BNJhLx.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx108556-NHjkz0BNJhLx.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx108556-NHjkz0BNJhLx.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/108556-iCiPfU0GU4OM.jpg", "description": "The master spy codenamed &lt;Twilight&gt; has spent his days on undercover missions, all for the dream of a better world. But one day, he receives a particularly difficult new order from command. For his mission, he must form a temporary family and start a new life?! A Spy/Action/Comedy about a one-of-a-kind family!<br><br>\n(Source: MANGA Plus)<br><br>\n<i>Notes:<br>\n- Nominated for the 24th Tezuka Osamu Cultural Prize in 2020.<br>\n- Nominated for the 13th and 14th Manga Taisho Award in 2020 and 2021.<br>\n- Nominated for the 44th Kodansha Manga Award in the Shounen Category in 2020.</i>", "chapters": null, "genres": ["Action", "Comedy", "Slice of Life", "Supernatural"], "averageScore": 83, "status": "RELEASING", "format": "MANGA", "countryOfOrigin": "JP"}, {"id": 30642, "title": {"romaji": "Vinland Saga", "english": "Vinland Saga"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx30642-0mjRDkf4THpo.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx30642-0mjRDkf4THpo.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx30642-0mjRDkf4THpo.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/30642-MeizzL2WDv6C.jpg", "description": "As a child, Thorfinn sat at the feet of the great Leif Ericson and thrilled to wild tales of a land far to the west. But his youthful fantasies were shattered by a mercenary raid. Raised by the Vikings who murdered his father, Thorfinn became a terrifying warrior, forever seeking to kill the band's leader, Askeladd, and avenge his father. Sustaining Thorfinn through his ordeal are his pride in his family and his dreams of a fertile westward land, a land without war or slavery … the land Leif called Vinland.\n<br><br>\n(Source: Kodansha USA)\n<br><br>\n<i>Notes:<br>\n- Includes the one-shot \"Sayonara ga Chikai no de\" (For Our Farewell Is Near)<br>\n- Includes the one-shot \"Assassin's Creed: Valhalla x Vinland Saga\"<br>\n- Includes two extra chapters.<br>\n- Won the Grand Prize at the Japan Media Arts Festival in 2009.<br>\n- Winner of the 36th Kodansha Manga Award in the General category in 2012.</i>", "chapters": 224, "genres": ["Action", "Adventure", "Drama"], "averageScore": 90, "status": "FINISHED", "format": "MANGA", "countryOfOrigin": "JP"}, {"id": 87423, "title": {"romaji": "Yakusoku no Neverland", "english": "The Promised Neverland"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx87423-gPNtu8QbGped.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx87423-gPNtu8QbGped.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx87423-gPNtu8QbGped.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/n87423-n5n0LZu9Gs5H.jpg", "description": "Emma, Norman and Ray are the brightest kids at the Grace Field House orphanage. And under the care of the woman they refer to as “Mom,” all the kids have enjoyed a comfortable life. Good food, clean clothes and the perfect environment to learn—what more could an orphan ask for? One day, though, Emma and Norman uncover the dark truth of the outside world they are forbidden from seeing.\n<br><br>\n(Source: VIZ Media)\n<br><br>\n<i>Note: Nominated to the 22nd, 23rd, and 25th Annual Tezuka Osamu Cultural Prize.</i>", "chapters": 181, "genres": ["Drama", "Fantasy", "Horror", "Mystery", "Psychological", "Thriller"], "averageScore": 79, "status": "FINISHED", "format": "MANGA", "countryOfOrigin": "JP"}];
  static final List<Map<String, dynamic>> _manhwaRaw = [{"id": 105398, "title": {"romaji": "Na Honjaman Level Up", "english": "Solo Leveling"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx105398-b673Vt5ZSuz3.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx105398-b673Vt5ZSuz3.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx105398-b673Vt5ZSuz3.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/105398-4UrEhdqZukrg.jpg", "description": "In a world where awakened beings called “Hunters” must battle deadly monsters to protect humanity, Seong Jin-U, nicknamed “the weakest hunter of all mankind,” finds himself in a constant struggle for survival. One day, after a brutal encounter in an overpowered dungeon wipes out his party and threatens to end his life, a mysterious System chooses him as its sole player: Jin-U has been granted the rare opportunity to level up his abilities, possibly beyond any known limits. Follow Jin-U’s journey as he takes on ever-stronger enemies, both human and monster, to discover the secrets deep within the dungeons and the ultimate extent of his powers.\n<br><br>\n(Source: Tappytoon)\n<br><br>\n<i>Note: Includes 22 extra chapters.</i>", "chapters": 201, "genres": ["Action", "Adventure", "Fantasy"], "averageScore": 84, "status": "FINISHED", "format": "MANGA", "countryOfOrigin": "KR"}, {"id": 119257, "title": {"romaji": "Jeonjijeok Dokja Sijeom", "english": "Omniscient Reader"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx119257-Pi21aq3ey9GG.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx119257-Pi21aq3ey9GG.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx119257-Pi21aq3ey9GG.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/119257-RtxJMRCunHXc.jpg", "description": "Back then, Dok-Ja had no idea. He had no idea his favorite web novel 'Three Ways to Survive the Apocalypse' was going to come to life, and that he would become the only person to know how the world was going to end. He also had no idea he would end up becoming the protagonist of this novel-turned-reality. Now, Dok-Ja will go on a journey to change the course of the story and save humankind once and for all.\n<br><br>\n(Source: WEBTOON, edited)", "chapters": null, "genres": ["Action", "Adventure", "Fantasy"], "averageScore": 86, "status": "RELEASING", "format": "MANGA", "countryOfOrigin": "KR"}, {"id": 85143, "title": {"romaji": "Sinui Tap", "english": "Tower of God"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx85143-23oup3ETbFJk.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx85143-23oup3ETbFJk.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx85143-23oup3ETbFJk.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/85143-IKyCdaJKfa2M.jpg", "description": "What do you desire? Money and wealth? Honor and pride? Authority and power? Revenge? Or something that transcends them all? Whatever you desire—it's here.<br><br>\n(Source: WEBTOON)", "chapters": null, "genres": ["Action", "Adventure", "Drama", "Fantasy", "Mystery"], "averageScore": 81, "status": "RELEASING", "format": "MANGA", "countryOfOrigin": "KR"}, {"id": 86964, "title": {"romaji": "Hurejasik", "english": "Bastard"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/b86964-vTdn1Esqw3va.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/b86964-vTdn1Esqw3va.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/b86964-vTdn1Esqw3va.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/86964-pdcp6HlZ66lq.jpg", "description": "High school life is hard enough, but it’s even harder for Seon Jin. A sickly disabled boy, Jin might as well be invisible. No one ever pays attention to him, except for the bullies who prey on him for being weak. Jin, however, keeps a very dark secret—there’s a serial killer in his house…and it’s his father!\n<br><br>\n(Source: Seven Seas Entertainment)\n<br><br>\n<i>Note: Includes one extra chapter.</i>", "chapters": 94, "genres": ["Drama", "Horror", "Mystery", "Psychological", "Romance", "Thriller"], "averageScore": 83, "status": "FINISHED", "format": "MANGA", "countryOfOrigin": "KR"}, {"id": 140407, "title": {"romaji": "Yeokdaegeum Yeongji Seolgyesa", "english": "The Greatest Estate Developer"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx140407-fJQr0fmqq1IO.png", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx140407-fJQr0fmqq1IO.png", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx140407-fJQr0fmqq1IO.png"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/140407-WMGs02Q3fFUb.jpg", "description": "When civil engineering student Su-Ho Kim falls asleep reading a fantasy novel, he wakes up as a character in the book! Su-Ho is now in the body of Lloyd Frontera, a lazy noble who loves to drink, and whose family is in a mountain of debt. Using his engineering knowledge, Su-Ho designs inventions to avert the terrible future that lies in wait for him. With the help of a giant hamster, a knight, and the world’s magic, can Su-Ho dig his new family out of debt and build a better future?\n<br><br>(Source: WEBTOON, edited)<br><br>\n<i>Note: Includes 12 extra chapters.</i>", "chapters": 222, "genres": ["Adventure", "Comedy", "Fantasy"], "averageScore": 90, "status": "FINISHED", "format": "MANGA", "countryOfOrigin": "KR"}, {"id": 128067, "title": {"romaji": "SSS-geup Jugeoya Saneun Hunter", "english": "SSS-Class Revival Hunter"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx128067-wnLBg6Cy1ncs.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx128067-wnLBg6Cy1ncs.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx128067-wnLBg6Cy1ncs.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/128067-F2qRPwWiCG7b.jpg", "description": "In the mysterious, RPG dungeon-like Tower, Confucius Kim lives a mundane existence, envying all the star hunters. One day, his wish for more is granted with a legendary skill to copy others’ abilities… at the cost of his life. Before he can make sense of it, he’s killed by the #1 hunter, the Flame Emperor! But this activates his skill and now he’s copied a new one, the ability to travel back in time upon death. How will Confucius use these skills to outplay the competition and rise to the top?\n<br><br>\n(Source: Tapas)", "chapters": null, "genres": ["Action", "Adventure", "Drama", "Fantasy", "Supernatural"], "averageScore": 83, "status": "RELEASING", "format": "MANGA", "countryOfOrigin": "KR"}, {"id": 100568, "title": {"romaji": "Supyeongseon", "english": "The Horizon"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx100568-4BC0PsdwU4bL.png", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx100568-4BC0PsdwU4bL.png", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx100568-4BC0PsdwU4bL.png"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/100568-BuzmQ7WSwG5H.jpg", "description": "A world where everything has been lost. A boy and a girl alone together. A spark of hope kindled between them. All they can do is move forward. But against broken adults and devastating despair, how long will they be able to keep going...?\n<br><br>\n(Source: Yen Press)", "chapters": 21, "genres": ["Adventure", "Drama", "Psychological"], "averageScore": 85, "status": "FINISHED", "format": "MANGA", "countryOfOrigin": "KR"}, {"id": 126297, "title": {"romaji": "Iphagyongbyeong", "english": "Teenage Mercenary"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx126297-SPiM7QtUnJ4P.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx126297-SPiM7QtUnJ4P.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx126297-SPiM7QtUnJ4P.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/126297-Axr0Xm5JFnhz.jpg", "description": "At the age of eight, I-Jin Yu lost his parents in a plane crash and became stranded in a foreign land, forced to become a child mercenary in order to stay alive. He returns home ten years later to be reunited with his family in Korea, where food and shelter are plenty and everything seems peaceful. But I-Jin will soon learn that life as a teenager is a whole other feat of survival. With only one year of high school left, I-Jin must master new tactics to maneuver his way around the schoolhouse battleground. Can he survive a year of high school? Or rather, will the school be able to survive him?<br>\n<br>\n(Source: WEBTOON)", "chapters": null, "genres": ["Action", "Drama"], "averageScore": 79, "status": "RELEASING", "format": "MANGA", "countryOfOrigin": "KR"}, {"id": 100954, "title": {"romaji": "Sweet Home", "english": "Sweet Home"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx100954-xY0Vw2sRRo8t.png", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx100954-xY0Vw2sRRo8t.png", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx100954-xY0Vw2sRRo8t.png"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/100954-y7f4uDwqvDny.jpg", "description": "After an unexpected family tragedy, a reclusive high school student is forced to leave his home -- only to face something much scarier: a reality where monsters are trying to wipe out humanity. Now he must fight alongside a handful of reluctant heroes to try and save the world before it’s too late.<br><br>\n(Source: WEBTOON)<br><br>\n<i>Note: Includes one extra chapter.</i>", "chapters": 141, "genres": ["Drama", "Horror", "Psychological", "Supernatural", "Thriller"], "averageScore": 82, "status": "FINISHED", "format": "MANGA", "countryOfOrigin": "KR"}, {"id": 85141, "title": {"romaji": "God of High School", "english": "The God of High School"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx85141-qHR957V3FVco.png", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx85141-qHR957V3FVco.png", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx85141-qHR957V3FVco.png"}, "bannerImage": null, "description": "Mori Jin is a high school student and Taekwondo specialist who enters \"The God of High School,\" a fighting tournament that promises the winner anything they want. What began as a competition to seek out the best high school fighter soon reveals itself to be part of a much greater plot that goes beyond Mori's wildest imagination. What will he give to become a true god?\n<br><br>\n(Source: WEBTOON)", "chapters": 569, "genres": ["Action", "Adventure", "Fantasy"], "averageScore": 76, "status": "FINISHED", "format": "MANGA", "countryOfOrigin": "KR"}, {"id": 137280, "title": {"romaji": "Na Honja Mallep Newbie", "english": "I’m the Max-Level Newbie"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx137280-juUL79K7f9s7.png", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx137280-juUL79K7f9s7.png", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx137280-juUL79K7f9s7.png"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/137280-I46ILENRzGYY.jpg", "description": "Kang Jin-Hyeok, a gaming streamer, and content creator is the only person who has cleared the game, [Tower of Trials]. However, as the game’s popularity declines, it becomes increasingly difficult for him to continue making a living as a content creator. Jinhyeok prepares to end his 11-year-long relationship with the game and say goodbye to his humble group of subscribers. But on that very day, the Tower of Trials appears in reality with a message saying that humanity will perish unless all players clear each floor within 90 days. Jin-Hyeok, who knows the game better than anyone, decides to use his knowledge to his advantage and dominate the tower. It’s time to show everyone what a hardcore gamer can do!\n<br><br>\n(Source: Tappytoon, edited)", "chapters": null, "genres": ["Action", "Fantasy"], "averageScore": 77, "status": "RELEASING", "format": "MANGA", "countryOfOrigin": "KR"}, {"id": 105393, "title": {"romaji": "Gwihwanjaui Mabeobeun Teukbyeolhaeya Hamnida", "english": "A Returner's Magic Should Be Special"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx105393-oiHumQoBGKG5.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx105393-oiHumQoBGKG5.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx105393-oiHumQoBGKG5.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/105393-ERoRkr9cT9B6.jpg", "description": "The worst calamity humankind has ever faced...\n<br><br>\nShadow Realms have ravaged the earth and decimated almost everyone in their way. The survival of humanity hinges upon the success of just six mages, including analytic fighter Desir Herrman. The remaining heroes make one final stand to end the bloodshed...but to no avail. Desir closes his eyes on what should be the end of his life—only to open them and see the beginning of his school days?! Desir has returned thirteen years back to the past, where he’s been given another chance. A chance to see the loved ones he lost, a chance to meet his fellow warriors again, and a chance to save the world…!\n<br><br>\n(Source: Yen Press)", "chapters": 268, "genres": ["Action", "Adventure", "Fantasy"], "averageScore": 76, "status": "FINISHED", "format": "MANGA", "countryOfOrigin": "KR"}];
  static final List<Map<String, dynamic>> _manhuaRaw = [{"id": 85734, "title": {"romaji": "Tamen De Gushi", "english": null}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx85734-yllpIVoPjADr.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx85734-yllpIVoPjADr.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx85734-yllpIVoPjADr.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/85734-d1rM3a9RVGuA.jpg", "description": "Sun Jing has a massive crush on a girl she sees at the bus station—feminine, blonde, and absolutely adorable, Qiu Tong is everything Sun Jing desires. But the tomboyish, outgoing Sun Jing cannot bring herself to utter a single word in Qiu Tong's presence. Once she musters up the courage, however, Sun Jing successfully introduces herself and secures a friendship with the cute girl. Although they are only friends for now, Sun Jing will do anything to see Qiu Tong smile; and with her genuine kindness, she might just win Qiu Tong's heart.\n<br><br>\n(Source: MAL Rewrite)", "chapters": null, "genres": ["Comedy", "Romance", "Slice of Life"], "averageScore": 82, "status": "RELEASING", "format": "MANGA", "countryOfOrigin": "CN"}, {"id": 86707, "title": {"romaji": "Yao Shen Ji", "english": "Tales of Demons and Gods"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx86707-QD3UyAOHUEaT.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx86707-QD3UyAOHUEaT.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx86707-QD3UyAOHUEaT.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/86707-3H7rwoNkGgBe.jpg", "description": "Because of the Space-Time Demon Spirit Book, time and space underwent a reversal. Though he was supposed to have died to demon beasts, Nie Li found himself sitting in a classroom when he opened his eyes. He had gone back to the age of thirteen. Now that everything has begun anew... how will he protect his beloved?<br>\n<br>\n(Source: Bilibili Comics)", "chapters": null, "genres": ["Action", "Adventure", "Fantasy", "Romance"], "averageScore": 77, "status": "RELEASING", "format": "MANGA", "countryOfOrigin": "CN"}, {"id": 100805, "title": {"romaji": "Here U Are", "english": "Here U Are"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx100805-3DCHMdZ5blWl.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx100805-3DCHMdZ5blWl.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx100805-3DCHMdZ5blWl.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/100805-DJWVyMhaHXHO.jpg", "description": "Sophomore Yu Yang is a real treasure. He has a cheerful, easy-going, and emphatic personality. Seniors look up to him, and he knows how to stand up for himself. Freshman Li Huan is moody and taciturn, haughty and, at times, outright rude. How will these two manage to get along, and where will it lead them..?\n<br>\n<br>\n(Source: Aloha Comics) <br>\n<br>\n<i>Note: Includes 20 extra chapters.</i>", "chapters": 157, "genres": ["Drama", "Romance", "Slice of Life"], "averageScore": 85, "status": "FINISHED", "format": "MANGA", "countryOfOrigin": "CN"}, {"id": 116353, "title": {"romaji": "Mo Huang Da Guanjia", "english": "The Devil Butler"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx116353-DYuIigXuPwpZ.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx116353-DYuIigXuPwpZ.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx116353-DYuIigXuPwpZ.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/116353-oRFNFjzfqWV1.jpg", "description": "As the Demon King, Yifan Zhuo uses his knowledge and power, collected over millennia, to defeat all foes, until the day he is betrayed. With his last breath, the demon king manages to reincarnate... but into the body of a puny young servant! To Yifan's dismay, the servant has a spirit bond with his mistress, Lady Luo. Yifan, now known as Fan, finds himself inexplicably drawn to Lady Luo and links his fate to her family. With Lady Luo at his side, will he regain his place as the Demon King?\n<br><br>\n(Source: Tapas)", "chapters": null, "genres": ["Action", "Fantasy"], "averageScore": 82, "status": "RELEASING", "format": "MANGA", "countryOfOrigin": "CN"}, {"id": 85850, "title": {"romaji": "19 Tian", "english": null}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/b85850-C9jxTZSRutBw.png", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/b85850-C9jxTZSRutBw.png", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/b85850-C9jxTZSRutBw.png"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/85850-QYuQiM5HkQyj.jpg", "description": "A group photo in kindergarten is the start of a lifetime friendship between Jian Yi and Zhan Zhengxi. They grew up together, and met good friends like He Tian and Mo Guanshan on campus.<br><br>\n\n\"19 Days\" not only shows the relaxed and happy school days of the four, but is also a story in which the boys come to understand each other and help each other grow up.<br><br>\n\n(Source: Tencent, translated)", "chapters": null, "genres": ["Comedy", "Romance", "Slice of Life"], "averageScore": 84, "status": "RELEASING", "format": "MANGA", "countryOfOrigin": "CN"}, {"id": 117324, "title": {"romaji": "Nan Hao Shang Feng", "english": null}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx117324-97mHyfJGwpBq.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx117324-97mHyfJGwpBq.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx117324-97mHyfJGwpBq.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/117324-gg0B1Pv4be8E.jpg", "description": "A comedy about two ordinary high school boys.", "chapters": null, "genres": ["Comedy", "Slice of Life"], "averageScore": 84, "status": "RELEASING", "format": "MANGA", "countryOfOrigin": "CN"}, {"id": 104494, "title": {"romaji": "Wu Lian Dianfeng", "english": "Martial Peak"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx104494-xmWuGEwxzbfB.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx104494-xmWuGEwxzbfB.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx104494-xmWuGEwxzbfB.jpg"}, "bannerImage": null, "description": "The peak of martial arts is solitary and lonely. It is an endless pursuit for unattainable heights as well. In order to surpass the limits of martial arts, growth and the will to survive in adverse situations is necessary.\nOne day, Yang Kai, a disciple-on-trial (and floor sweeper) of the Lingxiao Martial Arts Sect discovered a Wordless Black Book. That marked the turn in his luck and the beginning of his martial arts journey.\n<br><br>\n(Source: Webnovel)", "chapters": null, "genres": ["Action", "Adventure", "Ecchi", "Fantasy", "Romance", "Supernatural"], "averageScore": 73, "status": "RELEASING", "format": "MANGA", "countryOfOrigin": "CN"}, {"id": 112275, "title": {"romaji": "Tian Guan Ci Fu", "english": "Heaven Official's Blessing"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx112275-fh0u5cH2qB5b.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx112275-fh0u5cH2qB5b.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx112275-fh0u5cH2qB5b.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/112275-MI6MZ0HuZx1r.jpg", "description": "800 years ago, Xie Lian was a pure-blooded and noble Crown Prince, a well-regarded child of Heaven with unlimited potential. But who knew that, after he ascended and became a god with tens of thousands of worshippers, his fate would take such a sharp downhill turn? He was demoted again and again, and fell to rock bottom. 800 years later, Xie Lian ascended again, but this time, without worshippers or and without incense. One day, after returning from collecting scraps, he took a mysterious young man home. And this young man was the Ghost King that made others pale in fear whenever discussed—Hua Cheng.\n<br><br>\n(Source: Bilibili Comics)\n", "chapters": null, "genres": ["Adventure", "Drama", "Fantasy", "Romance"], "averageScore": 87, "status": "RELEASING", "format": "MANGA", "countryOfOrigin": "CN"}, {"id": 142287, "title": {"romaji": "Wo! Tian Mìng Da Fanpai", "english": "I Am The Fated Villain"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx142287-nlT7oSUzHnNv.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx142287-nlT7oSUzHnNv.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx142287-nlT7oSUzHnNv.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/142287-4O13ckpwfZvh.jpg", "description": "A transmigrator awoke in the world of martial arts and became the villain named Gu Changge. His goal is to harvest the luck of those called \"the Son of Fate\" in order to become the strongest. With the Sons of Fate as his deranged enemies, he changes the destiny of being a villain.<br><br>(Source: INKR)", "chapters": null, "genres": ["Action", "Adventure", "Drama", "Fantasy"], "averageScore": 76, "status": "RELEASING", "format": "MANGA", "countryOfOrigin": "CN"}, {"id": 107966, "title": {"romaji": "Wo Laopo Shi Mowang Daren", "english": "My Wife is the Demon Queen"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx107966-Onmu3ihQNKbO.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx107966-Onmu3ihQNKbO.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx107966-Onmu3ihQNKbO.jpg"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/107966-r2CIINtWsNOw.jpg", "description": "A normal powerless male protagonist is entrusted to look after the fallen demon queen Isabella. Depleted of her powers, Isabella is forced to camouflage as a human and suppress her regal status. Evil masterminds plot to dethrone a powerful demon queen in a medieval fantasy land.", "chapters": 460, "genres": ["Action", "Adventure", "Fantasy", "Romance"], "averageScore": 71, "status": "FINISHED", "format": "MANGA", "countryOfOrigin": "CN"}, {"id": 160980, "title": {"romaji": "Gao Wu: Denglu Weilai Yi Wan Nian", "english": "Log Into The Future"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx160980-KAM0gr3dSMvB.jpg", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx160980-KAM0gr3dSMvB.jpg", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx160980-KAM0gr3dSMvB.jpg"}, "bannerImage": null, "description": "300 years after mutated beasts ravaged the world, humanity began to lose ground, with only martial arts as their last line of defense. Lu Sheng mysteriously gains the power to journey 10,000 years into the future, only to find humanity has disappeared. However, he acquires the culminated martial arts wisdom to fight back against these monsters, honing his skills to the pinnacle. Armed with this new-found knowledge, can Lu Sheng emerge as the final beacon of hope for humanity's survival?\n<BR><BR>\n(Source: Tapas, edited)", "chapters": null, "genres": ["Action", "Drama", "Fantasy"], "averageScore": 71, "status": "RELEASING", "format": "MANGA", "countryOfOrigin": "CN"}, {"id": 101563, "title": {"romaji": "Modao Zushi", "english": "Grandmaster of Demonic Cultivation: Mo Dao Zu Shi"}, "coverImage": {"extraLarge": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/large/bx101563-nTBq5IEYYWbX.png", "large": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/medium/bx101563-nTBq5IEYYWbX.png", "medium": "https://s4.anilist.co/file/anilistcdn/media/manga/cover/small/bx101563-nTBq5IEYYWbX.png"}, "bannerImage": "https://s4.anilist.co/file/anilistcdn/media/manga/banner/101563-LSHPwTrTqVDl.jpg", "description": "Feared and hated for his sinister abilities, Wei Wuxian–the grandmaster of demonic cultivation–was driven to his death when the most powerful clans united to destroy him.<br>\n<br>\nThirteen years later, Wei Wuxian is reborn. Summoned by a young man who sacrificed his soul in a forbidden ritual, Wei Wuxian is now bound to seek vengeance on the stranger’s behalf or risk the destruction of his own soul. But when an evil entity emerges, a familiar face from Wei Wuxian’s past suddenly appears amidst the chaos–Lan Wangji, a powerful cultivator who will help shine a light on the dark truths that surround them.\n<br><br>\n(Source: Seven Seas Entertainment)", "chapters": 259, "genres": ["Action", "Adventure", "Comedy", "Drama", "Mystery", "Romance", "Supernatural"], "averageScore": 84, "status": "FINISHED", "format": "MANGA", "countryOfOrigin": "CN"}];
